with cte_invoice_settle_detail as (     --应收发票明细表    select         h.invoice_id      , b.id      , ROW_NUMBER() OVER (PARTITION BY h.invoice_id ORDER BY b.id) AS rn2      , h.no as se_no             --应收发票编号      , b.ro_no                   --订单编号      , coalesce(rb.parent_no,rs.parent_no) as parent_no --原结算单编号      , b.settle_no               --结算单编号      , b.settle_detail_id        --结算单明细ID      , st.store_name as biz_shop_saas_code      --实际营业店      --, udf.get_dict_enum_desc(&#x27;stg_se_invoice&#x27;,&#x27;business_type&#x27;,h.business_type) as business_type           --业务类型      , da_charge.name as charge_type_saas_code   --应收费用类型       , b.tax_rate                --税率      , b.tax_amount              --税额      , b.tax_free_amount         --不含税金额      , b.amount                  --价税合计      , h.total_amount            --开票金额      , b.invoice_settle_detail_id --应收发票结算明细表ID      , h.biz_shop_saas_code as store_cd    from stg.stg_se_invoice h    left join ods.ods_se_invoice_settle_detail_df b        on h.invoice_id = b.invoice_id and b.dt = &#x27;2026-07-09&#x27; and b.delete_flag = &#x27;0&#x27;    left join stg.stg_se_receivable rb         on rb.no = b.settle_no and rb.dt = &#x27;2026-07-09&#x27; and rb.delete_flag = &#x27;0&#x27;    left join stg.stg_se_finance_settle_base rs         on rs.settle_no = b.settle_no and rs.dt = &#x27;2026-07-09&#x27; and rs.delete_flag = &#x27;0&#x27;    left join dwd.dim_store st        on st.store_cd = h.biz_shop_saas_code and st.dt = &#x27;2026-07-09&#x27;    left join stg.stg_sys_expense_type_translation da_charge        on b.charge_type_saas_code = da_charge.code        and da_charge.dt = &#x27;2026-07-09&#x27;        and da_charge.delete_flag = &#x27;0&#x27;        and da_charge.lang_code = &#x27;ZH_CN&#x27;    where h.account_set_code &lt;&gt; &#x27;AS_0001&#x27; and h.dt = &#x27;2026-07-09&#x27; and h.delete_flag = &#x27;0&#x27; and b.id = &#x27;15307359&#x27;)--b.invoice_settle_detail_id = 1009170908--ds.tax_invoice_detail_id = 814846667467792385,cte_se_and_settle as (   --应收发票明细表合并核销流水    select t.*        --,ROW_NUMBER() OVER (PARTITION BY t.invoice_id,t.id ORDER BY t.rn4) AS rn5    from (        select             h.*            --,d.old_bill_no            --,d.old_receive_date            --,d.invoice_amount            --,d.invoice_amount_agg            --,d.operation_date            --,d.operation_type            ,ds.tax_invoice_detail_id            --,ROW_NUMBER() OVER (PARTITION BY h.invoice_id ORDER BY h.id,rn3) AS rn4            from cte_invoice_settle_detail h        left join ods.ods_se_invoice_split_detail_df s            on s.invoice_settle_detail_id = h.invoice_settle_detail_id            and s.dt = &#x27;2026-07-09&#x27;             and s.delete_flag = &#x27;0&#x27;        left join ods.ods_se_tax_invoice_detail_df ds            on ds.invoice_split_detail_id = s.invoice_split_detail_id            and ds.dt = &#x27;2026-07-09&#x27;             and ds.delete_flag = &#x27;0&#x27;        -- left join cte_se_transaction_flow d        --     on ds.tax_invoice_detail_id = d.tax_invoice_detail_id            ) t)select * from cte_se_and_settle
