流程节点表 stg_bpmi_tokencreate external table if not exists stg_bpmi_token (  tokenid string comment &#x27;pkid&#x27;,  tokenname string comment &#x27;节点名称&#x27;,  elementtype string comment &#x27;1&#x27;,  taskid string comment &#x27;任务ID 关联流程任务表&#x27;,  activityid string comment &#x27;1&#x27;,  actorid string comment &#x27;执行人ad&#x27;,  transitionid string comment &#x27;1&#x27;,  result string comment &#x27;1&#x27;,  formid string comment &#x27;1&#x27;,  tokenstatus string comment &#x27;节点状态&#x27;,  receivetime string comment &#x27;节点开始时间&#x27;,  finishtime string comment &#x27;节点结束时间&#x27;,  lastnotifytime string comment &#x27;1&#x27;,  expiretime string comment &#x27;1&#x27;,  notifyfrequence string comment &#x27;1&#x27;,  remark string comment &#x27;备注&#x27;,  isrecede string comment &#x27;1&#x27;,  curusername string comment &#x27;1&#x27;,  progressstatus string comment &#x27;1&#x27;,  standardtime string comment &#x27;1&#x27;,  fromaccount string comment &#x27;1&#x27;,  fromusername string comment &#x27;1&#x27;,  recyclelevel string comment &#x27;1&#x27;,  systemid string comment &#x27;1&#x27;,  curdeptname string comment &#x27;执行人部门名称&#x27;,  showinlist string comment &#x27;1&#x27;,  actiontype string comment &#x27;1&#x27;,  curdeptid string comment &#x27;执行人部门ID&#x27;) comment &#x27;stg_bpmi_token&#x27; partitioned by (dt string comment &#x27;日期&#x27;, et string comment &#x27;服务&#x27;) ROW FORMAT DELIMITED FIELDS TERMINATED BY &#x27;\\u0001&#x27; STORED AS TEXTFILE LOCATION &#x27;hdfs://prd-bd66110-zazk02.hd:8020/apps/hive/warehouse/stg.db/stg_bpmi_token&#x27; TBLPROPERTIES (  &#x27;comment&#x27; = &#x27;stg_bpmi_token&#x27;,  &#x27;transient_lastDdlTime&#x27; = &#x27;1680074687&#x27;,  &#x27;bucketing_version&#x27; = &#x27;2&#x27;,  &#x27;text.compress&#x27; = &#x27;BZIP2&#x27;);

处理笔记办公流程流程概况：该系统均为外采，涉及的表没有注释，数据没有做过标准化处理。为了统计不同维度的审批时效，常用关键字段如节点名称、节点备注过滤掉系统自动审批的节点。涉及问题1：背景：公司在经历3轮组织架构调整，如初期公司国内规模扩张有通用1，2，3，4，5，6部，中期合并为通用南、北部，目前仅有通用事业部（租赁业务逐渐向海外扩展）现状：部分节点有处理人，但是没有部门名称或者部门编码，由于系统外采，部门编码&#x2F;部门名称没有调整组织架构。
select curdeptid,curdeptname,cast(receivetime as date) receivetime ,actorid,tokenname,remarkfrom stg.stg_bpmi_tokenwhere dt = &#x27;2026-07-21&#x27; and cast(receivetime as date) &gt; cast(&#x27;2026-01-01&#x27; as date) and actorid is not nulland tokenname not like &#x27;%开始%&#x27; and tokenname not like &#x27;%申请人%&#x27; and remark not like &#x27;%自动%&#x27;--group by curdeptid,curdeptname--,receivetimeorder by receivetime

